import{_ as r,l,o as e,c as n,v as t,p as s,x as o,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"合并与拆分","description":"","frontmatter":{"title":"合并与拆分","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/coalescing-splitting.md","filePath":"cs/coalescing-splitting.md","lastUpdated":1789023840000}'),h={name:"cs/coalescing-splitting.md"};function g(_,a,m,A,B,u){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="合并与拆分" tabindex="-1">合并与拆分 <a class="header-anchor" href="#合并与拆分" aria-label="Permalink to &quot;合并与拆分&quot;">​</a></h1><div class="epigraph"><p>合并把拷贝两端收成同一颜色，删 `mov`；拆分把长区间切开，降低度数、给调度和调用点喘息。二者都改冲突图，而不是改源程序。</p><footer>—— 据 Chaitin 合并；George and Appel, Iterated Register Coalescing, 1996；Cooper 等 live range splitting 整理</footer></div><p>上一课<a href="/cs/chaitin-briggs">Chaitin–Briggs</a> 的图上来自 SSA 析构的大量拷贝。缺口是<strong>合并</strong>（coalescing）与<strong>拆分</strong>（splitting）。保守合并：不增加 \\(deg\\ge K\\) 的风险。激进合并再拆开。本课钉权衡，不写表调度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>φ 析构与参数传递产生 <code>mov</code>。若两端无冲突，应收成同一虚名。过度合并拉长区间，度数升高，反而 spill。拆分：在循环外、调用点切开，插入新 <code>mov</code>，换更可着色的图。缺口是<strong>何时并、何时拆</strong>，不是简化栈。</p><p>George–Appel：在简化过程中迭代合并。</p><h3 id="合并不是-gvn" tabindex="-1">合并不是 GVN <a class="header-anchor" href="#合并不是-gvn" aria-label="Permalink to &quot;合并不是 GVN&quot;">​</a></h3><p>GVN 删的是计算；合并删的是寄存器传送。值已相同，只是名不同。</p><p><span class="marginnote">George–Appel 1996。Hack 等 SSA 上合并。本课与线性扫描的区间拆分对照：同一思想，表示不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>保守：Briggs/George 准则。若拷贝在循环外、两端冲突则放弃或先拆。拆分点：循环边界、call、高压力块。</p>',11)),(e(),s(c,null,{default:o(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MOV%5B%22%E6%8B%B7%E8%B4%9D%22%5D%20--%3E%20COA%5B%22%E5%90%88%E5%B9%B6%22%5D%0A%20%20LIVE%5B%22%E9%95%BF%E5%8C%BA%E9%97%B4%22%5D%20--%3E%20SPL%5B%22%E6%8B%86%E5%88%86%22%5D%0A%20%20COA%20--%3E%20IG%5B%22%E6%9B%B4%E6%96%B0%E5%86%B2%E7%AA%81%E5%9B%BE%22%5D%0A%20%20SPL%20--%3E%20IG%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与重物化：常数拆分后可 remat 代替传送。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>SSA 上合并要保持常规形式。析构后再合并更简单。不要合并跨越不同寄存器类（int/float）。</p><p>调试：合并后两个源变量同一寄存器，调试器要靠位置列表——DWARF 后课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写最优拆分 NP 证明。后课默认：拷贝用合并压，压力用拆分泄。下一课表调度：分配前后都可能调度，顺序与拆分交互。</p><p>也不把拆分当多线程 fork。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>合并消 <code>mov</code>；过并增度数。</li><li>拆分缩短区间，服务调用点与循环。</li><li>迭代合并（George–Appel）是标准工程。</li><li>出处：Chaitin；George and Appel, 1996；对照 Poletto 区间。</li></ul>',9))])}const S=r(h,[["render",g]]);export{E as __pageData,S as default};
